import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import assert from 'node:assert/strict';

const root = fs.realpathSync(path.dirname(fileURLToPath(import.meta.url)));
const output = path.resolve(root, 'dist');
const files = ['index.html', ...fs.readdirSync(root).filter(name => /\.(js|css)$/.test(name)),
  ...fs.readdirSync(path.join(root, 'vendor')).filter(name => name.endsWith('.js')).map(name => 'vendor/' + name)];

// All current models, textures and thumbnails are generated by the runtime.
// Ship only the page, styles and browser modules; keep tools and references local.
for (const file of files) {
  const source = path.join(root, file);
  assert.equal(fs.realpathSync(source), source, 'Build inputs must not be links');
  assert(fs.statSync(source).isFile(), 'Missing runtime file: ' + file);
}
assert.equal(path.dirname(output), root);
assert.equal(path.basename(output), 'dist');
if (fs.existsSync(output)) {
  assert.equal(fs.realpathSync(output), output, 'Refusing linked output directory');
  fs.rmSync(output, { recursive: true });
}
fs.mkdirSync(output);
let bytes = 0;
for (const file of files) {
  const target = path.join(output, file);
  fs.mkdirSync(path.dirname(target), { recursive: true });
  fs.copyFileSync(path.join(root, file), target);
  bytes += fs.statSync(target).size;
}
console.log(JSON.stringify({ output, files: files.length, bytes, networkDependencies: false }));
